import numpy as np
def equation(t, A, params):
    return (params[0] + params[1]*np.sqrt(t)*np.log(t) + params[2]*A*np.log(A) + params[3]*A**2*np.log(A)
            + params[4]*A + params[5]*A**2 + params[6]*np.sqrt(t) + params[7]*np.sqrt(t)*np.log(t)*A
            + params[8]*A**3 + params[9]*t**2/A)
